def copy_notebook_tags(apps, schema_editor):
    """Move each entry's notebook-only tags into the biobank-wide vocabulary.

    A tag that already exists there (any letter case) is reused; the old
    list is left untouched so the previous release keeps working.
    """
    Entry = apps.get_model("core", "NotebookEntry")
    Tag = apps.get_model("core", "Tag")
    resolved = {}
    for entry in Entry.objects.prefetch_related("tags").iterator(chunk_size=200):
        linked = []
        for old in entry.tags.all():
            name = " ".join(old.name.split())
            if not name:
                continue
            if name.lower() not in resolved:
                resolved[name.lower()] = (
                    Tag.objects.filter(name__iexact=name).first()
                    or Tag.objects.create(name=name)
                )
            linked.append(resolved[name.lower()])
        if linked:
            entry.shared_tags.add(*linked)


